/**
 * An in-thread request to allow an agent action (`design/components/approval-card.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/approval-card.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Icon,
  agentMember,
  claimSlot,
  createDerived,
  elementRef,
  resolveSlot,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/approval-card.module.css'
import Button from '../controls/Button'

export type ApprovalDecision = NonNullable<ApprovalCardProps['decision']>

export type ApprovalTone = NonNullable<ApprovalCardProps['tone']>

export interface ApprovalCardProps {
  /**
   * The approve button's text (generic default `Allow`), which localized hosts replace.
   */
  approveLabel?: string
  /**
   * The details, such as a ToolCall, a CodeBlock or a DescriptionList.
   */
  children?: JSX.Element
  /**
   * The recorded decision, which replaces the actions with the outcome.
   */
  decision?: 'denied' | 'approved'
  /**
   * The deny button's text (generic default `Deny`).
   */
  denyLabel?: string
  description?: string
  /**
   * The outcome text for each decision (generic defaults `Allowed` / `Denied`).
   */
  messages?: { approved: string; denied: string }
  onApprove: () => void
  onDeny: () => void
  /**
   * The decision being sent, which puts that button in its loading state and disables the other.
   */
  pending?: 'denied' | 'approved'
  /**
   * The action, phrased as a question the reader can answer, such as "Run `rm -rf dist`?"
   */
  title: string
  /**
   * `warning` for a normal request, `danger` for an action that cannot be undone.
   */
  tone?: 'warning' | 'danger'
}

/** An in-thread request to allow an agent action. */
export default function ApprovalCard(given: ApprovalCardProps): JSX.Element {
  const props = mergeProps(
    {
      tone: 'warning',
      approveLabel: 'Allow',
      denyLabel: 'Deny',
      messages: (() => ({ approved: 'Allowed', denied: 'Denied' }))(),
    } as Defaults<ApprovalCardProps, 'tone' | 'approveLabel' | 'denyLabel' | 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const card = elementRef<HTMLElement>()
    const childrenSlot = resolveSlot(() => props.children)
    const titleId = createDerived(() => `${uid}-title`)
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'ApprovalCard',
        element: () => card.value,
        state: () => ({
          title: props.title,
          decision: props.decision ?? '',
          pending: props.pending ?? '',
        }),
        actions: {},
        withholds: () => card.value,
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <section
        class={styles.card}
        aria-labelledby={titleId.value}
        data-tone={props.tone}
        data-decision={props.decision}
        data-state={props.pending === undefined ? undefined : 'loading'}
        aria-busy={props.pending === undefined ? undefined : 'true'}
        data-member="approval-card"
        ref={card.attach}
      >
        {/* head */}
        <div class={styles.head}>
          {/* glyph */}
          <span class={styles.glyph}>
            <Icon name={props.tone === 'danger' ? 'error' : 'warning'} />
          </span>
          {/* copy */}
          <div class={styles.copy}>
            {/* title */}
            <p class={styles.title} id={titleId.value}>
              {props.title}
            </p>
            {props.description !== undefined ? (
              <p class={styles.description}>{props.description}</p>
            ) : null}
          </div>
        </div>
        {childrenSlot.filled() ? <div class={styles.details}>{childrenSlot()}</div> : null}
        {props.decision === undefined ? (
          <div class={styles.actions}>
            <Button
              variant="solid"
              tone={props.tone === 'danger' ? 'danger' : 'accent'}
              size="sm"
              label={props.approveLabel}
              loading={props.pending === 'approved'}
              disabled={props.pending === 'denied'}
              onClick={() => props.onApprove?.()}
            />
            <Button
              variant="outline"
              tone="neutral"
              size="sm"
              label={props.denyLabel}
              loading={props.pending === 'denied'}
              disabled={props.pending === 'approved'}
              onClick={() => props.onDeny?.()}
            />
          </div>
        ) : (
          <p class={styles.outcome}>
            {/* outcomeGlyph */}
            <span class={styles.outcomeGlyph}>
              <Icon name={props.decision === 'approved' ? 'confirm' : 'denied'} size="sm" />
            </span>
            {props.decision === 'approved' ? props.messages.approved : props.messages.denied}
          </p>
        )}
      </section>
    )
  })
}
